506:   const age = ageOf();
507:   const mood = computeMood();
508:   const moodName = t(mood.charAt(0).toUpperCase() + mood.slice(1));
509:   const hudAvatar = $('#hudAvatar');
510:   if (hudAvatar) {
511:     hudAvatar.dataset.mood = mood;
