890:   const lore = {
891:     storm: 'Their storms still answer to the old names. They resent new thunder.',
892:     death: 'They keep a ledger of every soul, including yours.',
893:     love: 'They collect devotion the way other gods collect swords.',
894:     war: 'They have never lost a war. They are careful about which wars they start.',
895:     wisdom: 'They know what you are planning. They have known for some time.',
