485:     if (changes[k]) parts.push(`${changes[k] > 0 ? '+' : ''}${changes[k]} ${t(map[k])}`);
486:   }
487:   if (changes.followers) parts.push(`${changes.followers > 0 ? '+' : ''}${fmt(changes.followers)} ${t('souls')}`);
