817: function effectTags(effects = {}) {
818:   const out = [];
819:   for (const [k, label] of [['faith', 'Faith'], ['power', 'Power'], ['wisdom', 'Wisdom'], ['influence', 'Influence']]) {
820:     if (effects[k]) out.push(tagHtml(`${effects[k] > 0 ? '+' : ''}${effects[k]} ${t(label)}`, effects[k] > 0));
821:   }
822:   if (effects.followersPct) out.push(tagHtml(t('{n}% Souls', { n: (effects.followersPct > 0 ? '+' : '') + Math.round(effects.followersPct * 100) }), effects.followersPct > 0));
823:   if (effects.relic) out.push(tagHtml(t('+ Relic'), true));
824:   return out.join('');
825: }
