827: function openEventModal(rawEv) {
828:   const ev = localizedEvent(rawEv);
829:   openModal(`${closeBtn()}
830:     <div class="modal-kicker">${esc(t('Aeon {n} · Omen', { n: roman(state.aeon) }))}</div>
831:     <h2>${esc(ev.title)}</h2>
832:     <p class="modal-text">${esc(ev.text)}</p>
833:     <div class="choice-list">${ev.choices.map((c, i) => {
834:       const ok = affordableEffects(c.effects);
835:       return `<button class="choice" data-choice="${i}" ${ok ? '' : 'disabled'}>
836:         <span class="ch-label">${esc(c.label)}</span>
837:         <span class="ch-tags">${effectTags(c.effects)}</span>
838:       </button>`;
839:     }).join('')}</div>`);
840:   $$('#modalRoot .choice').forEach(btn => btn.addEventListener('click', () => {
841:     if (btn.disabled) return;
842:     const choiceIndex = Number(btn.dataset.choice);
