810: function closeBtn() { return `<button class="modal-close" data-close aria-label="${esc(t('Close'))}">${icon('close')}</button>`; }
811: function affordableEffects(effects = {}) {
812:   for (const k of ['faith', 'power']) {
813:     if (effects[k] < 0 && state.stats[k] < -effects[k]) return false;
814:   }
