851:     const tags = changeTags(out.changes).map(t => tagHtml(t, !t.startsWith('-'))).join('');
852:     openModal(`${closeBtn()}
853:       <div class="modal-kicker">${esc(ev.title)}</div>
854:       <p class="modal-text">${esc(out.result)}</p>
855:       ${out.relic ? `<p class="modal-text" style="color:var(--gold)">${t('You also gain the relic <b>{relic}</b>.', { relic: esc(out.relic.name) })}</p>` : ''}
856:       <div class="result-changes">${tags || tagHtml(t('The story moves on'), true)}</div>
857:       <div class="modal-actions"><button class="btn primary" data-close>${esc(t('Continue'))}</button></div>`);
858:     if (canAscend(state)) setTimeout(() => toast(t('The way to {name} is open', { name: rankName(RANKS[state.rank + 1]) })), 400);
859:   }));
