585: export function missingReason(state, action) {
586:   if ((state.ap || 0) < action.ap) return `Requires ${action.ap} actions`;
587:   for (const [k, v] of Object.entries(action.cost || {})) {
588:     if ((k === 'faith' || k === 'power') && state.stats[k] < v) return `Requires ${v} ${k}`;
589:   }
590:   return '';
591: }
