871:   const victoryText = victory
872:     ? `<p class="modal-text">${esc(t('The Twenty Thrones are silent. One by one, the elder powers incline their heads. The mortal world will tell this story until the last star burns out — the story of the god who climbed from a single prayer to the hand that turns the wheel of myth.'))}</p>`
873:     : `<p class="modal-text">${esc(t(info.to.lore))}</p>`;
874:   openModal(`<div class="ascend-glyph">${icon(victory ? 'wheel' : 'crown')}</div>
875:     <div class="modal-kicker">${esc(victory ? t('The summit of the divine order') : t('Aeon {n} · Apotheosis', { n: roman(state.aeon) }))}</div>
876:     <h2>${esc(victory ? t('Supreme Architect') : rankName(info.to))}</h2>
