879:     <div class="ascend-gains">${gains}</div>
880:     <div class="modal-actions">${victory
881:       ? `<button class="btn ghost" data-new>${esc(t('Begin a New Myth'))}</button><button class="btn primary" data-close>${esc(t('Continue Eternally'))}</button>`
