516:   $('#hudAvatarInner').innerHTML = renderPortrait(state.god, { age, crop: 'face' });
517:   $('#hudAvatarBadge').innerHTML = icon(DOMAIN_ICONS[d.id]);
518:   const moodLine = $('#moodLine');
519:   if (moodLine) {
520:     moodLine.dataset.mood = mood;
521:     moodLine.style.setProperty('--mood', MOOD_COLORS[mood]);
522:     moodLine.innerHTML = `<span class="mood-dot"></span><span>${esc(t('{mood} · {age} years', { mood: moodName, age }))}</span>`;
523:   }
524:   $('#hudName').textContent = state.god.name;
525:   $('#hudRank').textContent = rankName(rank);
526:   $('#hudEpithet').textContent = `${t(state.god.epithet)} · ${t(state.god.pantheon)} · ${ageLabel(age)}`;
527:   $('#hudMight').textContent = fmt(might);
528:   $('#hudStanding').textContent = '#' + stand.rank;
529:   $('#hudAeon').textContent = t('Aeon {n}', { n: roman(state.aeon) });
530:   $('#hudDomain').textContent = domainName(d);
531: 
532:   $('#gamePortrait').innerHTML = renderPortrait(state.god, { age });
533:   $('#cardName').textContent = state.god.name;
534:   $('#cardSub').textContent = `${rankName(rank)} · ${domainName(d)} · ${ageLabel(age)}`;
535:   $('#cardMight').textContent = fmt(might);
536:   const next = RANKS[state.rank + 1];
537:   const curNeed = rank.need;
538:   const pct = next ? Math.max(0, Math.min(100, ((might - curNeed) / (next.need - curNeed)) * 100)) : 100;
539:   $('#mightBar').style.width = pct + '%';
540:   if (next && might < next.need) {
541:     $('#mightNext').textContent = t('{n} more might to become {name}', { n: fmt(next.need - might), name: rankName(next) });
542:   } else if (next) {
543:     $('#mightNext').textContent = t('The way to {name} is open.', { name: rankName(next) });
544:   } else {
545:     $('#mightNext').textContent = t('You stand at the summit of the divine order.');
546:   }
547:   $('#cardFollowers').textContent = fmt(state.followers);
548:   const delta = state.followerDelta || 0;
549:   $('#followersTrend').textContent = delta > 0 ? `+${fmt(delta)}` : delta < 0 ? `${fmt(delta)}` : '';
550:   $('#followersTrend').className = 'trend' + (delta < 0 ? ' down' : '');
551: 
552:   $('#statGrid').innerHTML = ['faith', 'power', 'wisdom', 'influence'].map(k =>
553:     `<div class="stat-cell" title="${esc(t(k.charAt(0).toUpperCase() + k.slice(1)))}">${icon(STAT_ICONS[k])}<div><span class="sv">${fmt(state.stats[k])}</span><span class="sl">${esc(t(k))}</span></div></div>`).join('');
554: 
555:   const ascBtn = $('#ascendBtn');
556:   const ready = canAscend(state);
557:   if (!next) {
558:     ascBtn.disabled = true;
559:     ascBtn.classList.remove('ready');
560:     ascBtn.innerHTML = `<span class="asc-main">${icon('crown')} ${esc(t('Supreme Architect'))}</span><span class="asc-sub">${esc(t('The summit is yours'))}</span>`;
561:   } else if (ready) {
562:     ascBtn.disabled = false;
563:     ascBtn.classList.add('ready');
564:     ascBtn.innerHTML = `<span class="asc-main">${icon('crown')} ${esc(t('Ascend to {name}', { name: rankName(next) }))}</span><span class="asc-sub">${esc(t('The heavens are watching'))}</span>`;
565:   } else {
566:     ascBtn.disabled = true;
567:     ascBtn.classList.remove('ready');
568:     ascBtn.innerHTML = `<span class="asc-main">${icon('crown')} ${esc(t('Ascend'))}</span><span class="asc-sub">${esc(t('{n} might required', { n: fmt(next.need - might) }))}</span>`;
569:   }
570: 
571:   $('#raceChips').innerHTML = state.races.map((r, i) =>
572:     `<button class="race-chip" data-race="${i}" title="${esc(t(r.traitName))}"><span class="dot" style="background:${r.color};color:${r.color}"></span>${esc(r.name)}</button>`).join('');
573:   $('#relicList').innerHTML = state.relics.length
574:     ? state.relics.map((r, i) => `<div class="relic-row" data-relic="${i}">${icon('gem')}<span>${esc(r.name)}</span><b>+${fmt(r.power)}</b></div>`).join('')
575:     : `<div class="relic-empty">${esc(t('No relics yet. Make something holy.'))}</div>`;
576:   $('#relicCount').textContent = state.relics.length ? `${state.relics.length} ${t('forged')}` : '';
577:   renderRelationshipBox();
578:   $('#stickNote').hidden = !state.attractiveStick;
579: 
580:   renderActions();
581:   renderVillage();
582:   renderLog();
583:   renderBoard(stand, might);
584:   saveGame();
