957: function openGodMeeting(rival) {
958:   let rel = relationshipWith(rival.name);
959:   if (!rel) {
960:     rel = { name: rival.name, affection: 0, met: false, status: 'Distant' };
961:     state.relationships.push(rel);
962:   }
963:   const dd = domainOf(rival.domain);
964:   const meetDisabled = rel.met;
965:   const maxed = rel.affection >= 100;
966:   openModal(`${closeBtn()}
967:     <div class="modal-kicker">A god of ${esc(domainName(dd))} · ${esc(t(rival.pantheon))}</div>
968:     <div class="rival-card"><div class="rival-sigil" style="overflow:hidden">${rivalPortrait(rival)}</div><div><h2>${esc(rival.name)}</h2><div class="rival-meta">${esc(t(rival.epithet))}</div></div></div>
969:     <p class="modal-text">You find ${esc(rival.name)} beneath an arch of cloud-marble. The conversation can become a friendship, a rivalry, or something the bards will exaggerate.</p>
970:     <div class="relationship-meter"><span>${esc(relationStatus(rel.affection))}</span><strong>${rel.affection}<small> / 100</small></strong><i><b style="width:${rel.affection}%"></b></i></div>
971:     <div class="social-actions">
972:       <button class="choice" id="meetGod" ${meetDisabled ? 'disabled' : ''}><span class="ch-label">${meetDisabled ? 'Already introduced' : 'Make an introduction'}</span><span class="ch-tags">${meetDisabled ? 'A first meeting is remembered.' : '+8 affection · free'}</span></button>
973:       <button class="choice" id="shareAmbrosia" ${maxed || state.stats.faith < 8 ? 'disabled' : ''}><span class="ch-label">Share ambrosia</span><span class="ch-tags">8 faith · +12 affection</span></button>
974:       <button class="choice" id="giftLaurel" ${maxed || state.stats.power < 6 ? 'disabled' : ''}><span class="ch-label">Gift a laurel of starlight</span><span class="ch-tags">6 power · +10 affection</span></button>
975:     </div>
976:     <div class="modal-actions"><button class="btn ghost" id="backOlympus">Back to Olympus</button></div>`, 'social-modal');
977:   const updateRelation = (amount, message, cost) => {
978:     if (cost && (state.stats.faith < (cost.faith || 0) || state.stats.power < (cost.power || 0))) return;
979:     if (cost) { state.stats.faith -= cost.faith || 0; state.stats.power -= cost.power || 0; }
980:     rel.affection = Math.min(100, rel.affection + amount);
981:     rel.status = relationStatus(rel.affection);
982:     rel.met = true;
983:     addLog(state, 'star4', `${state.god.name} ${message} ${rival.name}.`, 'divine');
984:     renderGame(); saveGame(); playSound('action');
985:     openGodMeeting(rival);
986:   };
987:   $('#meetGod').addEventListener('click', () => { if (!rel.met) updateRelation(8, 'met', null); });
988:   $('#shareAmbrosia').addEventListener('click', () => updateRelation(12, 'shared ambrosia with', { faith: 8 }));
989:   $('#giftLaurel').addEventListener('click', () => updateRelation(10, 'presented a laurel of starlight to', { power: 6 }));
990:   $('#backOlympus').addEventListener('click', openOlympus);
991: }
