464: function loadSaved() {
465:   try {
466:     const raw = localStorage.getItem(SAVE_KEY);
467:     if (!raw) return false;
468:     const parsed = JSON.parse(raw);
469:     if (!parsed || !parsed.god || typeof parsed.followers !== 'number') return false;
470:     state = parsed;
471:     if (!state.lastRanks) state.lastRanks = {};
472:     if (!state.age) state.age = 18 + Math.max(0, (state.aeon || 1) - 1) * 3;
