474:     if (!Array.isArray(state.salonPurchases)) state.salonPurchases = [];
475:     if (typeof state.attractiveStick !== 'boolean') state.attractiveStick = false;
476:     state.locale = uiLang;
477:     return true;
478:   } catch (e) { return false; }
